// The text of each generated file, from its owner's facts. Pure: the entry (main.ts) reads the owners and writes the
// files; everything here takes values and answers text, so the tests can feed it anything. Literals are written by
// the `literal` the caller gives (JSON text, which TypeScript and Python both read), so this file holds no JSON code.
import * as Arr from "effect/Array";
import * as Rec from "effect/Record";
import { OUTPUTS } from "./sources.ts";

/** How a value is written as a literal: JSON text, indented. */
export type Literal = (value: unknown) => string;

type Output = keyof typeof OUTPUTS;

/** The first line of every generated file, which says so (AGENTS.md, "Generate"). */
export const header = (output: Output, comment: "//" | "#"): string =>
  `${comment} Generated by \`pnpm generate\` from ${OUTPUTS[output].from}. Never edit it: change that and run \`pnpm generate\`.\n`;

/** The ABI module: one `as const` ABI per compiled contract or interface, in the order given. */
export const renderAbi = (abis: ReadonlyArray<{ readonly name: string; readonly abi: unknown }>, literal: Literal) =>
  header("abi", "//") +
  "// The ABIs of the compiled contracts and interfaces that Capxul's off-chain code uses (packages/generate,\n" +
  "// src/sources.ts lists them). Imported by the blueprint, Core and the indexer, so they cannot disagree.\n" +
  Arr.join(
    Arr.map(abis, ({ name, abi }) => `\nexport const ${name} = ${literal(abi)} as const;\n`),
    "",
  );

/** One tier of Companies House, as the deployment record holds it. */
export interface Tier {
  readonly tier: string;
  readonly namespace: string;
  readonly companyNamespace: string;
  readonly member: string;
}

/** What the seeded table is made from: the deployment record and two facts of the seed. */
export interface Seeded {
  readonly chainId: number;
  readonly companiesHouse: string;
  readonly companiesHouseRoles: string;
  readonly createCall: string;
  readonly tiers: ReadonlyArray<Tier>;
  /** Each deployed contract's address, by its name in the record. */
  readonly contracts: Readonly<Record<string, string>>;
  /** The addresses the Installer was built with (its constructor's `config`), by their names there. */
  readonly installer: Readonly<Record<string, string>>;
  /** The seed's last block. */
  readonly head: { readonly number: number; readonly timestamp: number };
  /** Anvil's first test account at the seed's head: its nonce and the address of the next contract it creates. */
  readonly firstAccount: { readonly address: string; readonly nonce: number; readonly nextContract: string };
}

const constant = (doc: string, name: string, value: string) => `\n/** ${doc} */\nexport const ${name} = ${value};\n`;

/** The seeded table: where everything the seed deployed is, on every world's chain. */
export const renderSeeded = (seeded: Seeded, literal: Literal) =>
  header("seeded", "//") +
  "// What the seeded chain (state/core.json) holds, as the deployment record and the seed say. Imported by Core and\n" +
  "// packages/world, so no address of the seed is typed twice.\n" +
  constant("The chain id the seed runs under.", "chainId", `${seeded.chainId}`) +
  constant(
    "Companies House: the Safe whose Roles module holds each tier's roles.",
    "companiesHouse",
    literal(seeded.companiesHouse),
  ) +
  constant("Companies House's Roles module.", "companiesHouseRoles", literal(seeded.companiesHouseRoles)) +
  constant("Safe's CreateCall library, as the deployment used it.", "createCall", literal(seeded.createCall)) +
  constant(
    "Companies House's tiers: each one's namespaces and its member.",
    "tiers",
    `${literal(seeded.tiers)} as const`,
  ) +
  constant("Each deployed contract's address, by its name.", "contracts", `${literal(seeded.contracts)} as const`) +
  constant(
    "The addresses the Installer was built with: the deployed contracts it installs and the outside ones (Hats, Safe's modules) as the seed has them.",
    "installer",
    `${literal(seeded.installer)} as const`,
  ) +
  constant(
    "The seed's last block: a world's clock cannot start before it.",
    "head",
    `${literal(seeded.head)} as const`,
  ) +
  constant(
    "Anvil's first test account at the seed's head: its nonce, and the address its next contract creation lands at.",
    "firstAccount",
    `${literal(seeded.firstAccount)} as const`,
  );

/** The names of a company's site the Capxul app uses, from the blueprint's vocabulary. */
export interface SiteNames {
  /** The Capxul app's field on a Supplier, Customer and Employee that holds the party's payment address. */
  readonly WALLET_ADDRESS_FIELD: string;
  /** The Capxul app's daily job, by its method. */
  readonly DAILY_JOB: string;
  /** The daily job's Scheduled Job Type, by the name the blueprint gives it. */
  readonly DAILY_JOB_TYPE: string;
  /** The start of the company Safe's ledger account's name. */
  readonly SAFE_ACCOUNT_PREFIX: string;
}

/** The Python module of the site's names. */
export const renderSite = (names: SiteNames, literal: Literal) =>
  header("site", "#") +
  '"""The names of a company\'s site the Capxul app shares with the blueprint (packages/blueprint, Site)."""\n' +
  Arr.join(
    Arr.map(Rec.toEntries(names), ([name, value]) => `\n${name} = ${literal(value)}\n`),
    "",
  );

/** The generated folder's package file. */
export const renderSitePackage = () => header("sitePackage", "#");
